public sealed class CreditReviewSqlTests(SqlFixture fixture):CreditRequirementsSqlBase(fixture),IClassFixture<SqlFixture>,IDisposable
{
    private WebApplicationFactory<Program>? staffFactory;private Task<HttpClient> Staff(string role)=>base.Staff(role,staffFactory??=sql.Factory.WithWebHostBuilder(_=>{}));public void Dispose()=>staffFactory?.Dispose();
    private async Task<JsonNode> Submitted(HttpClient customer,HttpClient finance)
    {
        var current=(await Publish(finance,Content("human-review")with{Documents=[]}))["current"]!;var app=await Draft(customer);var accepted=await Read(await customer.PostAsJsonAsync("/api/credit/applications/"+Value(app,"id")+"/consents/"+Id(),Acceptance(app,current)));return await Submit(customer,accepted["application"]!);
    }
    private async Task<JsonNode> Submit(HttpClient customer,JsonNode app)
    {
        var path="/api/credit/applications/"+Value(app,"id");var ready=await Read(await customer.GetAsync(path+"/submission"));Assert.True(ready["canSubmit"]!.GetValue<bool>());return await Read(await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),new SubmitCreditApplicationInput(Value(ready["application"]!,"version"),Value(ready,"consentId"),Value(ready,"requirementsRevisionId"),Value(ready,"requirementsVersion"),"fa","ساختگی و بدون تعهد واقعی",true)));
    }
    private static string CustomerBase(JsonNode submission)=>"/api/credit/applications/"+Value(submission["application"]!,"id");private static string StaffBase(JsonNode submission)=>CustomerBase(submission).Replace("/api/credit/","/api/admin/credit/");
    private static ReviewCreditApplicationInput Input(JsonNode s,string outcome="Returned")=>new(Value(s["application"]!,"version"),Value(s["submission"]!,"id"),outcome,"fa","دلیل انسانی ساختگی آزمون 😀؛ فاقد تصمیم واقعی دربارهٔ شخص",outcome=="Approved"?"9007199254740993":null,outcome=="Approved"?DateTimeOffset.UtcNow.AddHours(1):null,true);
    private static async Task<JsonNode> Wire(HttpResponseMessage response,string name){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");if(Environment.GetEnvironmentVariable("SHOP_CREDIT_REVIEW_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,name+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,name+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,cacheControl=response.Headers.CacheControl?.ToString()}));}return JsonNode.Parse(raw)!;}}
    [Fact]public async Task ReturnAllowsExplicitResubmissionThenApprovalRetainsBothImmutableDecisionsAndHistoricalReceiptsWithoutOrdering()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var first=await Submitted(customer,finance);var path=StaffBase(first);var command=Id();var input=Input(first);var ready=await Wire(await reviewer.GetAsync(path+"/review"),"ready");Assert.True(ready["canReview"]!.GetValue<bool>());var returned=await Wire(await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input),"returned");Assert.Equal("Draft",Value(returned["application"]!,"state"));var reviewId=Value(returned["review"]!,"id");var detail=await Wire(await customer.GetAsync(CustomerBase(first)+"/reviews/"+reviewId),"customer-returned");Assert.Equal(input.Note,Value(detail,"note"));
        var second=await Submit(customer,returned["application"]!);Assert.NotEqual(Value(first["submission"]!,"id"),Value(second["submission"]!,"id"));var approved=await Wire(await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),Input(second,"Approved")),"approved");Assert.Equal("Approved",Value(approved["application"]!,"state"));Assert.Equal("9007199254740993",Value(approved["review"]!,"approvedAmountRial"));var history=await Wire(await customer.GetAsync(CustomerBase(first)+"/reviews"),"history");Assert.Equal(2,history["items"]!.AsArray().Count);var historical=await Wire(await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input),"returned-replay");Assert.True(historical["replayed"]!.GetValue<bool>());Assert.Equal("Draft",Value(historical["application"]!,"state"));await Wire(await reviewer.GetAsync(path+"/reviews/commands/"+command),"returned-receipt");await Wire(await customer.GetAsync(CustomerBase(first)+"/reviews/"+Value(approved["review"]!,"id")),"customer-approved");
        using(var stale=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),Input(second,"Declined")))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);using(var cancel=await customer.PutAsJsonAsync(CustomerBase(first)+"/cancel/"+Id(),new CancelCreditApplicationInput(Value(approved["application"]!,"version"))))Assert.Equal(HttpStatusCode.Conflict,cancel.StatusCode);var cap=await Wire(await customer.GetAsync(CustomerBase(first)+"/submission"),"approved-submission-capabilities");Assert.False(cap["canSubmit"]!.GetValue<bool>());Assert.False(cap["canWithdraw"]!.GetValue<bool>());var docs=await Wire(await customer.GetAsync(CustomerBase(first)+"/documents"),"approved-documents");Assert.False(docs["canUpload"]!.GetValue<bool>());
        await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var id=Value(first["application"]!,"id");var row=await db.ApplicationReviews.AsNoTracking().SingleAsync(x=>x.Id==reviewId);Assert.DoesNotContain(input.Note,Encoding.UTF8.GetString(row.ProtectedNote));Assert.Equal(2,await db.ApplicationReviews.CountAsync(x=>x.ApplicationId==id));Assert.Equal(2,await db.Submissions.CountAsync(x=>x.ApplicationId==id));Assert.Equal(2,await db.ReviewCommands.CountAsync(x=>x.ApplicationId==id));Assert.Equal(6,await db.ApplicationEvents.CountAsync(x=>x.ApplicationId==id));Assert.Empty(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.ToArrayAsync());Assert.Empty(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Reservations.ToArrayAsync());
    }
    [Fact]public async Task DeclineIsTerminalAndOtherOwnersFinanceManagersAndUnconfirmedOrInvalidApprovalsCannotDecideOrReadPrivateHistory()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var stranger=await Customer();using var other=stranger.Client;var sub=await Submitted(customer,finance);var path=StaffBase(sub);var input=Input(sub,"Approved");
        foreach(var invalid in new[]{input with{ReviewConfirmed=false},input with{ApprovedAmountRial="9007199254740994"},input with{ApprovedAmountRial="1.1"},input with{ExpiresAt=DateTimeOffset.UtcNow.AddSeconds(-1)},input with{ExpiresAt=null},input with{Note=""}})using(var denied=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),invalid))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);
        using(var denied=await finance.PostAsJsonAsync(path+"/reviews/commands/"+Id(),input))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await customer.PostAsJsonAsync(CustomerBase(sub)+"/reviews/commands/"+Id(),input))Assert.Contains(denied.StatusCode,new[]{HttpStatusCode.NotFound,HttpStatusCode.MethodNotAllowed});var decided=await Wire(await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),Input(sub,"Declined")),"declined");Assert.Equal("Declined",Value(decided["application"]!,"state"));Assert.Null(decided["review"]!["approvedAmountRial"]);var reviewId=Value(decided["review"]!,"id");foreach(var suffix in new[]{"/reviews","/reviews/"+reviewId})using(var denied=await other.GetAsync(CustomerBase(sub)+suffix))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);using(var denied=await reviewer.GetAsync(path+"/reviews?ownerId=forged"))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);using(var denied=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),input with{ApplicationVersion=Value(decided["application"]!,"version")}))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
    }
    [Fact]public async Task AuditRollbackAndConcurrentReplayPreserveOneDecisionAndAWithdrawalRaceHasOnlyOneWinner()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var sub=await Submitted(customer,finance);var path=StaffBase(sub);var id=Value(sub["application"]!,"id");var input=Input(sub);var command=Id();await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<IdentityContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_CreditReviewAuditFailure CHECK ([Action]<>'CREDIT_REVIEW')");}
        try{using var failed=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_CreditReviewAuditFailure");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var row=await db.Applications.AsNoTracking().SingleAsync(x=>x.Id==id);Assert.Equal("Submitted",row.State);Assert.Null(row.CurrentReviewId);Assert.Equal(input.ApplicationVersion,Convert.ToBase64String(row.Version));Assert.Empty(await db.ApplicationReviews.Where(x=>x.ApplicationId==id).ToArrayAsync());Assert.Empty(await db.ReviewCommands.Where(x=>x.ApplicationId==id).ToArrayAsync());Assert.Equal(3,await db.ApplicationEvents.CountAsync(x=>x.ApplicationId==id));}
        var results=await Task.WhenAll((await Task.WhenAll(reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input),reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input))).Select(x=>Read(x)));Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());Assert.Single(results,x=>!x["replayed"]!.GetValue<bool>());using(var conflict=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,input with{Note="different"}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);
        var second=await Submitted(customer,finance);var raceInput=Input(second,"Declined");var responses=await Task.WhenAll(reviewer.PostAsJsonAsync(StaffBase(second)+"/reviews/commands/"+Id(),raceInput),customer.PutAsJsonAsync(CustomerBase(second)+"/cancel/"+Id(),new CancelCreditApplicationInput(raceInput.ApplicationVersion)));Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var response in responses)response.Dispose();await using var final=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await final.ServiceProvider.GetRequiredService<CreditDbContext>().ApplicationReviews.CountAsync(x=>x.ApplicationId==id));
    }
    [Fact]public async Task ReadOnlyClaimsAndPendingMfaCannotDecideAndAnotherReviewerCannotReadActorScopedReceipts()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var secondReviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var sub=await Submitted(customer,finance);var path=StaffBase(sub);var original=reviewer.DefaultRequestHeaders.Authorization!;var handler=new JwtSecurityTokenHandler();var jwt=handler.ReadJwtToken(original.Parameter);string Token(IEnumerable<Claim> claims)=>handler.WriteToken(new JwtSecurityToken(jwt.Issuer,jwt.Audiences.Single(),claims.Where(x=>x.Type is not("exp"or"nbf")),DateTime.UtcNow.AddSeconds(-1),DateTime.UtcNow.AddMinutes(2),new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(new string('q',80))),SecurityAlgorithms.HmacSha256)));
        reviewer.DefaultRequestHeaders.Authorization=new("Bearer",Token(jwt.Claims.Where(x=>!(x.Type=="permission"&&x.Value=="credit.write"))));var readOnly=await Read(await reviewer.GetAsync(path+"/review"));Assert.False(readOnly["canReview"]!.GetValue<bool>());Assert.False(readOnly["canApprove"]!.GetValue<bool>());using(var denied=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),Input(sub)))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        reviewer.DefaultRequestHeaders.Authorization=new("Bearer",Token(jwt.Claims.Where(x=>x.Type!="token_kind").Append(new Claim("token_kind","mfa_pending"))));using(var denied=await reviewer.GetAsync(path+"/review"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),Input(sub)))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        reviewer.DefaultRequestHeaders.Authorization=original;var command=Id();await Read(await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+command,Input(sub)));using(var denied=await secondReviewer.GetAsync(path+"/reviews/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);using(var denied=await reviewer.PostAsJsonAsync(path+"/reviews/commands/"+Id(),new{applicationVersion=Value(sub["application"]!,"version"),submissionId=Value(sub["submission"]!,"id"),outcome="Returned",locale="fa",note="synthetic",reviewConfirmed=true,approvedAmountRial=(string?)null,expiresAt=(string?)null,ownerId="forged"}))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);
    }
    [Fact]public async Task SameCaseForeignKeysAndSqlChecksProtectReviewPointersAndGuardedDownCannotPartiallyRemoveHistory()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var first=await Submitted(customer,finance);var reviewed=await Read(await reviewer.PostAsJsonAsync(StaffBase(first)+"/reviews/commands/"+Id(),Input(first,"Approved")));var other=await Submitted(customer,finance);var id=Value(first["application"]!,"id");var otherSub=Value(other["submission"]!,"id");var reviewId=Value(reviewed["review"]!,"id");await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var fk=await Assert.ThrowsAsync<SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[Applications] SET [CurrentSubmissionId]={otherSub} WHERE [Id]={id}"));Assert.Equal(547,fk.Number);var missingAmount=await Assert.ThrowsAsync<SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ApplicationReviews] SET [ApprovedAmountRial]=NULL WHERE [Id]={reviewId}"));Assert.Equal(547,missingAmount.Number);var migrationSource=(await db.Database.GetAppliedMigrationsAsync()).ToArray();var down=await Assert.ThrowsAsync<SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027084339_CreditSubmissionSnapshots"));Assert.Equal(51000,down.Number);await db.Database.MigrateAsync();Assert.Equal(migrationSource,await db.Database.GetAppliedMigrationsAsync());Assert.False(db.Database.HasPendingModelChanges());Assert.Single(await db.ApplicationReviews.Where(x=>x.ApplicationId==id).ToArrayAsync());
    }
